echo "--- avd.log"; cat /tmp/avd.log; echo "--- sdkmanager.log tail"; tail -5 /tmp/sdkmanager.log; echo "--- avd dirs"; ls -la ~/.android ~/.android/avd 2>&1 | head -20; echo "--- env"; env | grep -E "ANDROID|HOME=" ; echo "--- list avd"; export PATH=$ANDROID_HOME/cmdline-tools/latest/bin:$PATH; avdmanager list avd 2>&1 | head -20; echo "--- images"; ls $ANDROID_HOME/system-images/android-34/google_apis/ 2>&1; ls $ANDROID_HOME/emulator | head -3
